  function normalize(code) {
    code = String(code || "").trim().toLowerCase().replace(/_/g, "-").split("-")[0];
    return LANGUAGES[code] ? code : "en";
  }

  const loadedLanguages = new Set(["pl", "en"]);
  if (PACKS.tr && Object.keys(PACKS.tr).length >= Object.keys(TEXT).length) loadedLanguages.add("tr");

  async function loadLanguage(language) {
    const code = normalize(language);
    if (loadedLanguages.has(code)) return code;
    const response = await fetch(`/locale/ui/${code}`, { cache: "no-store" });
    if (!response.ok) throw new Error(`Brak pełnego pakietu językowego ${code}: HTTP ${response.status}`);
    const extra = await response.json();
    if (!extra || typeof extra !== "object" || Array.isArray(extra)) throw new Error(`Nieprawidłowy pakiet językowy ${code}`);
    Object.assign(PACKS[code], extra);
    const missing = Object.keys(TEXT).filter(key => !Object.prototype.hasOwnProperty.call(PACKS[code], key));
    if (missing.length) throw new Error(`Pakiet ${code} jest niepełny: brakuje ${missing.length} tłumaczeń (${missing.slice(0, 8).join(", ")})`);
    loadedLanguages.add(code);
    return code;
  }

